-- CHECK 5: Q8 · listTopArtistByYear 2023 = the paper's result (USA Taylor Swift 12, UK Adele 12, …)
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'DECLARE @r TABLE (Country NVARCHAR(50), ArtistID INT, ArtistName NVARCHAR(100), Tong INT);
INSERT INTO @r EXEC listTopArtistByYear 2023;
DECLARE @ref TABLE (Country NVARCHAR(50), ArtistID INT, ArtistName NVARCHAR(100), Tong INT);
WITH x AS (SELECT ar.Country, ar.ID AS ArtistID, ar.Name AS ArtistName, COUNT(pt.TrackID) AS Tong FROM Artists ar LEFT JOIN Albums al ON al.ArtistID = ar.ID LEFT JOIN Tracks t ON t.AlbumID = al.ID LEFT JOIN PlaylistTracks pt ON pt.TrackID = t.ID AND pt.AddedDate >= DATEFROMPARTS(2023, 1, 1) AND pt.AddedDate < DATEFROMPARTS(2023 + 1, 1, 1) GROUP BY ar.Country, ar.ID, ar.Name)
INSERT INTO @ref SELECT * FROM x a WHERE Tong = (SELECT MAX(Tong) FROM x b WHERE b.Country = a.Country);
SET @ok = IIF(NOT EXISTS (SELECT * FROM @r EXCEPT SELECT * FROM @ref) AND NOT EXISTS (SELECT * FROM @ref EXCEPT SELECT * FROM @r) AND (SELECT COUNT(*) FROM @r) = (SELECT COUNT(*) FROM @ref), 1, 0);
